import{_ as d,o as t,c as a,ag as o}from"./chunks/framework.BZohXCq9.js";const f=JSON.parse('{"title":"Admin Dashboard -> Refund Requests (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/admin-dashboard/refund-requests.md","filePath":"modules/admin-dashboard/refund-requests.md"}'),r={name:"modules/admin-dashboard/refund-requests.md"};function s(l,e,i,n,u,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="admin-dashboard-refund-requests-deep" tabindex="-1">Admin Dashboard -&gt; Refund Requests (deep) <a class="header-anchor" href="#admin-dashboard-refund-requests-deep" aria-label="Permalink to &quot;Admin Dashboard -&gt; Refund Requests (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>admin-dashboard</code><br><strong>Feature:</strong> <code>refund-requests</code><br><strong>Route:</strong> <code>/admin-dashboard/refund-requests</code></p><p>This module is the admin review queue for lesson refund requests created by students.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all refund requests with status tabs (<code>all</code>, <code>pending</code>, <code>approved</code>, <code>rejected</code>).</li><li>Let admins approve or reject pending requests.</li><li>Enforce refund business rules before money moves.</li><li>Record refund and reversal transactions after approval.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/admin-dashboard/AdminRefundRequestsPage.tsx</code></td><td>Main route page</td><td>Calls <code>GET_REFUND_REQUESTS</code>, <code>APPROVE_REFUND_REQUEST</code>, <code>REJECT_REFUND_REQUEST</code>; renders table, tabs, reject dialog, and toasts.</td></tr><tr><td><code>Frontend/src/graphql/mutations/refundRequest.ts</code></td><td>Shared refund GraphQL</td><td>Defines admin operations and student refund operations in the same file.</td></tr></tbody></table><h2 id="frontend-graphql-used-by-admin-page" tabindex="-1">Frontend GraphQL used by admin page <a class="header-anchor" href="#frontend-graphql-used-by-admin-page" aria-label="Permalink to &quot;Frontend GraphQL used by admin page&quot;">​</a></h2><h3 id="get-refund-requests" tabindex="-1"><code>GET_REFUND_REQUESTS</code> <a class="header-anchor" href="#get-refund-requests" aria-label="Permalink to &quot;`GET_REFUND_REQUESTS`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/refundRequest.ts</code></li><li>Query field: <code>getRefundRequests(status: RefundRequestStatus)</code></li><li>Used by: <code>AdminRefundRequestsPage.tsx</code></li><li>Note: the page passes <code>undefined</code> for the <code>all</code> tab so backend returns every request</li></ul><h3 id="approve-refund-request" tabindex="-1"><code>APPROVE_REFUND_REQUEST</code> <a class="header-anchor" href="#approve-refund-request" aria-label="Permalink to &quot;`APPROVE_REFUND_REQUEST`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/refundRequest.ts</code></li><li>Mutation field: <code>approveRefundRequest(id: ID!)</code></li><li>Used by: approve button in <code>AdminRefundRequestsPage.tsx</code></li></ul><h3 id="reject-refund-request" tabindex="-1"><code>REJECT_REFUND_REQUEST</code> <a class="header-anchor" href="#reject-refund-request" aria-label="Permalink to &quot;`REJECT_REFUND_REQUEST`&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/refundRequest.ts</code></li><li>Mutation field: <code>rejectRefundRequest(id: ID!, rejectionReason: String)</code></li><li>Used by: reject dialog in <code>AdminRefundRequestsPage.tsx</code></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/refundRequest.typeDefs.js</code></li><li>Main enum: <ul><li><code>RefundRequestStatus</code></li></ul></li><li>Main type: <ul><li><code>RefundRequest</code></li></ul></li><li>Query fields: <ul><li><code>getRefundRequests(status: RefundRequestStatus): [RefundRequest!]!</code></li><li><code>getMyRefundRequests: [RefundRequest!]!</code></li></ul></li><li>Mutation fields: <ul><li><code>requestRefund(bookingId: ID!, slotId: ID!): RefundRequest!</code></li><li><code>approveRefundRequest(id: ID!): RefundRequest!</code></li><li><code>rejectRefundRequest(id: ID!, rejectionReason: String): RefundRequest!</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/refundRequest.resolver.js</code></li><li>Query resolvers: <ul><li><code>getRefundRequests</code><ul><li>Admin-only</li><li>Optional status filter</li><li>Sorts newest request first</li></ul></li><li><code>getMyRefundRequests</code><ul><li>Student-only</li><li>Used by student dashboard, not this admin page</li></ul></li></ul></li><li>Mutation resolvers relevant to this module: <ul><li><code>approveRefundRequest</code><ul><li>Admin-only</li><li>Validates request exists and is still pending</li><li>Re-loads booking and slot</li><li>Rejects approval when: <ul><li>slot already refunded</li><li>payout already happened</li><li>slot is <code>completed</code> or <code>missed</code></li><li>lesson date has passed</li></ul></li><li>Uses Stripe helpers: <ul><li><code>getTransferIdFromPaymentIntent</code></li><li><code>createTransferReversal</code></li><li><code>createRefund</code></li></ul></li><li>Updates booking slot to <code>refund</code></li><li>Marks <code>paymentStatus = refunded</code></li><li>Creates financial records through <code>createTransaction</code></li><li>Updates <code>teacherAvailabilityModel</code></li><li>Marks the refund request <code>approved</code></li></ul></li><li><code>rejectRefundRequest</code><ul><li>Admin-only</li><li>Marks request as rejected</li><li>Saves <code>processedAt</code>, <code>processedBy</code>, optional <code>rejectionReason</code></li></ul></li></ul></li><li>Mutation that feeds this module: <ul><li><code>requestRefund</code><ul><li>Student-only</li><li>Creates the pending refund request the admin later sees here</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/refundRequest.model.js</code></td><td>Stores refund requests</td></tr><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Source of slot/booking state during approval</td></tr><tr><td><code>server/src/models/teacherAvailability.model.js</code></td><td>Mirrors refund status into availability</td></tr><tr><td><code>server/src/services/stripeService.js</code></td><td>Executes Stripe refund and transfer reversal actions</td></tr><tr><td><code>server/src/services/transactionService.js</code></td><td>Creates transaction ledger rows after approval</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student side creates a refund request with <code>requestRefund</code>.</li><li>Admin opens <code>AdminRefundRequestsPage.tsx</code>.</li><li><code>GET_REFUND_REQUESTS</code> loads all or filtered requests.</li><li>Approve button -&gt; <code>APPROVE_REFUND_REQUEST</code>.</li><li>Backend re-validates the request, processes Stripe refund/reversal, updates booking + transactions + availability, then marks the request approved.</li><li>Reject button -&gt; <code>REJECT_REFUND_REQUEST</code>.</li><li>Backend records the rejection metadata and returns the updated request.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This page is only the admin queue. The creation side of the flow lives in student refund UI, but both halves share the same GraphQL module file.</li><li>The resolver intentionally re-checks all refund rules at approval time so the request cannot become invalid between creation and admin action.</li><li>The page disables both approve and reject flows while one request action is running, which helps avoid race conditions in the UI.</li></ul>',25)])])}const p=d(r,[["render",s]]);export{f as __pageData,p as default};
